R=[]
def rule(fam, eng, brand, markets, ttype, cond, channel, theme, reason, params=None, prio=50, launch=False, timing="this_week", owner="brand", notes=""):
    R.append(dict(id=f"R{len(R)+1:03d}", family=fam, engine=eng, brand=brand, markets=markets, trigger_type=ttype,
                  enabled_at_launch=launch, condition=cond, action=dict(channel=channel, content_theme=theme, timing=timing),
                  priority=prio, reason_template=reason, parameters=params or {}, owner=owner, notes=notes))
