F="field_events_feedback"
rule(F,"optimiser","all",ALL,"none","channel == 'rep_visit'","capacity","none","Rep visit slots this week: {rep_capacity_slots_week}; fill by return per slot",launch=True,prio=0,owner="field")
rule(F,"optimiser","all",ALL,"none","channel == 'kam_brief'","capacity","none","KAM briefs this week: {kam_capacity_week}; fill by return per brief",launch=True,prio=0,owner="field")
rule(F,"optimiser","all",ALL,"none","expected_return <= 0","drop","none","Not sent: expected return {expected_return} is not positive",launch=True,prio=0)
rule(F,"optimiser","all",ALL,"none","tier == 'A' and touches_month == 0 and week_of_month >= 3","floor","efficacy","Floor: tier A physician untouched this month gets one touch",launch=False,prio=0)
rule(F,"rules","all",ALL,"opportunity","event_upcoming_days <= 14 and event_registered == True","rep_email","event_reminder","Event in {event_upcoming_days} days: reminder from the rep",launch=False,prio=50)
rule(F,"rules","all",ALL,"opportunity","event_attended_days_ago <= 7","marketing_email","event_follow_up","Attended {event_attended_days_ago} days ago: follow-up with the materials",launch=False,prio=60)
rule(F,"feedback","all",ALL,"none","last_dismiss_reason == 'seen_recently'","adjust","none","Extend this physician's rep gap by {extend_days} days",dict(extend_days=14),launch=True,prio=0)
rule(F,"feedback","all",ALL,"none","last_dismiss_reason == 'routing'","adjust","none","Batch with other suggestions in the same area next week",launch=False,prio=0)
rule(F,"feedback","all",ALL,"none","last_dismiss_reason == 'wrong_content'","adjust","none","Mark theme {content_theme} as not relevant for this physician; move to the next theme",launch=False,prio=0)
rule(F,"feedback","all",ALL,"none","rule_accept_rate_30d < {min_accept_rate} and rule_triggers_30d >= 20","propose","none","Rule {rule_id} accepted {rule_accept_rate_30d}% of the time: propose a threshold change at the monthly review",dict(min_accept_rate=0.4),launch=True,prio=0)
fams={}
for r in R: fams[r['family']]=fams.get(r['family'],0)+1
launch=sum(1 for r in R if r['enabled_at_launch'])
print(len(R), launch, fams)
